module digit_product_counter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [9:0] L,\n    input wire [9:0] R,\n    output reg [31:0] count_1,\n    output reg [31:0] count_2,\n    output reg [31:0] count_3,\n    output reg [31:0] count_4,\n    output reg [31:0] count_5,\n    output reg [31:0] count_6,\n    output reg [31:0] count_7,\n    output reg [31:0] count_8,\n    output reg [31:0] count_9,\n    output reg done\n);\n\n    // State declarations with explicit widths\n    localparam [1:0] IDLE      = 2'd0;\n    localparam [1:0] COMPUTE   = 2'd1;\n    localparam [1:0] INCREMENT = 2'd2;\n    localparam [1:0] DONE_ST   = 2'd3;\n\n    reg [1:0] state;\n    reg [9:0] current_number;\n    reg [4:0] cycle_count;\n    localparam [4:0] MAX_CYCLES = 5'd20;\n\n    // Computation registers\n    reg [9:0] temp_num;\n    reg [15:0] current_product;\n    reg [3:0] current_digit;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize ALL registers\n            state <= IDLE;\n            done <= 1'b0;\n            count_1 <= 32'd0;\n            count_2 <= 32'd0;\n            count_3 <= 32'd0;\n            count_4 <= 32'd0;\n            count_5 <= 32'd0;\n            count_6 <= 32'd0;\n            count_7 <= 32'd0;\n            count_8 <= 32'd0;\n            count_9 <= 32'd0;\n            current_number <= 10'd0;\n            temp_num <= 10'd0;\n            current_product <= 16'd0;\n            current_digit <= 4'd0;\n            cycle_count <= 5'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize counters and start computation\n                        count_1 <= 32'd0;\n                        count_2 <= 32'd0;\n                        count_3 <= 32'd0;\n                        count_4 <= 32'd0;\n                        count_5 <= 32'd0;\n                        count_6 <= 32'd0;\n                        count_7 <= 32'd0;\n                        count_8 <= 32'd0;\n                        count_9 <= 32'd0;\n                        current_number <= L;\n                        state <= COMPUTE;\n                        cycle_count <= 5'd0;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (cycle_count == 5'd0) begin\n                        // Start product computation\n                        temp_num <= current_number;\n                        current_product <= 16'd1;\n                        cycle_count <= cycle_count + 5'd1;\n                    end else if (temp_num != 10'd0) begin\n                        // Extract digit and multiply\n                        current_digit <= temp_num % 10'd10;\n                        temp_num <= temp_num / 10'd10;\n                        cycle_count <= cycle_count + 5'd1;\n\n                        if (current_digit != 4'd0) begin\n                            current_product <= current_product * current_digit;\n                        end\n                    end else if (current_product >= 16'd10) begin\n                        // Need further reduction\n                        temp_num <= current_product;\n                        current_product <= 16'd1;\n                        cycle_count <= 5'd1;\n                    end else begin\n                        // Final digit ready\n                        state <= INCREMENT;\n                        cycle_count <= 5'd0;\n                    end\n\n                    // Safety exit condition\n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= INCREMENT;\n                        cycle_count <= 5'd0;\n                    end\n                end\n\n                INCREMENT: begin\n                    // Update appropriate counter\n                    case (current_product)\n                        16'd1: count_1 <= count_1 + 32'd1;\n                        16'd2: count_2 <= count_2 + 32'd1;\n                        16'd3: count_3 <= count_3 + 32'd1;\n                        16'd4: count_4 <= count_4 + 32'd1;\n                        16'd5: count_5 <= count_5 + 32'd1;\n                        16'd6: count_6 <= count_6 + 32'd1;\n                        16'd7: count_7 <= count_7 + 32'd1;\n                        16'd8: count_8 <= count_8 + 32'd1;\n                        16'd9: count_9 <= count_9 + 32'd1;\n                        default: ; // Skip other values\n                    endcase\n\n                    // Move to next number\n                    if (current_number == R) begin\n                        state <= DONE_ST;\n                    end else begin\n                        current_number <= current_number + 10'd1;\n                        state <= COMPUTE;\n                        cycle_count <= 5'd0;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule